    #[inline(always)]
    #[allow(clippy::too_many_arguments)]
    pub const fn new(s: T, e23: T, e31: T, e12: T) -> Self {
        Rotor { c: [s, e23, e31, e12] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
